    elements.push(`<button class="chain-label ${selected===c.id?'selected':''}" data-select="${c.id}" data-drop-chain="${c.id}" data-drop-index="0" style="left:${cx-87}px;top:${y}px;--accent:${color}" title="${esc(c.description||'Edit chain or drop a photo to its beginning')}"><span class="chain-line"></span><span class="chain-name">${esc(c.title)}</span>${ico('edit')}</button>`);
    let previousY=y+38,py=y+74;
    c.items.forEach((item,index)=>{
      if(item.kind==='photo'){
        const photo=data.photos[item.id];if(!photo)return;const size=M.photoDimensions(photo,data.photoSize);drop(c,index,cx,py-18);line(cx,previousY,cx,py,color);
        elements.push(`<div class="photo-card ${selected===photo.id?'selected':''}" style="left:${cx-size.width/2}px;top:${py}px;width:${size.width}px;height:${size.height}px;--accent:${color}" draggable="true" data-photo="${photo.id}" data-select="${photo.id}" data-drop-chain="${c.id}" data-drop-index="${index+1}" tabindex="0" role="button" aria-label="${esc(photo.title)}. Select to edit or move; drag to another chain."><img src="${photo.src}" style="width:${size.imageWidth}px;height:${size.imageHeight}px" alt="${esc(photo.title)}" draggable="false"><div class="photo-label"><span>${esc(photo.title)}</span>${ico('more')}</div><button class="branch-mini" style="top:${Math.round(size.imageHeight/2)}px" data-split="${photo.id}" title="Add a junction after this photo" aria-label="Add a junction after ${esc(photo.title)}">${ico('branch')}</button></div>`);
        positions.set(photo.id,{x:cx,y:py,w:size.width,h:size.height,group:g.id});previousY=py+size.height;py+=size.height+44;
      }else{
        drop(c,index,cx,py-18);line(cx,previousY,cx,py,color);drawNode(item,cx,py,color,g);previousY=py+66;py+=66;
      }
    });
