  layout={width:totalWidth,height:maxY,positions};world.style.width=totalWidth+'px';world.style.height=maxY+'px';world.innerHTML=`<svg class="connections" width="${totalWidth}" height="${maxY}" aria-hidden="true">${paths.join('')}</svg>`+elements.join('');applyZoom();
