function renderTray(){const placed=M.placed(data),photos=Object.values(data.photos).filter(p=>!placed.has(p.id));const tray=$('#tray');tray.hidden=!trayOpen;$('#library-nav').classList.toggle('active',trayOpen);$('#canvas-nav').classList.toggle('active',!trayOpen);if(!trayOpen)return;tray.innerHTML=`<div class="tray-head"><div><h3>Photo tray <span class="photo-counter">${photos.length} unplaced</span></h3><p>Drag a photo into a chain. Or select it, then choose “Move to a chain”.</p></div><button class="icon-button" data-toggle-tray aria-label="Close photo tray">${ico('close')}</button></div><div class="tray-items" data-drop-tray>${photos.map(p=>`<div class="tray-photo ${selected===p.id?'selected':''}" draggable="true" data-photo="${p.id}" data-select="${p.id}" tabindex="0" role="button" aria-label="${esc(p.title)}"><img src="${p.src}" alt="${esc(p.title)}" draggable="false"><span>${esc(p.title)}</span></div>`).join('')||'<p class="tray-empty">All your photos have a place. Add more photos to keep exploring.</p>'}</div>`;}
function select(id){selected=id;renderNavigation();world.querySelectorAll('.selected').forEach(el=>el.classList.remove('selected'));world.querySelectorAll('[data-select]').forEach(el=>{if(el.dataset.select===id)el.classList.add('selected');});renderInspector();renderTray();inspector.classList.add('mobile-open');}
function applyZoom(){world.style.transform=`scale(${zoom})`;sizer.style.width=Math.max(viewport.clientWidth,layout.width*zoom+40)+'px';sizer.style.height=Math.max(viewport.clientHeight,layout.height*zoom+40)+'px';$('#zoom-value').textContent=Math.round(zoom*100)+'%';}
function setZoom(value,clientX,clientY){const rect=viewport.getBoundingClientRect(),px=clientX===undefined?viewport.clientWidth/2:clientX-rect.left,py=clientY===undefined?viewport.clientHeight/2:clientY-rect.top;const wx=(viewport.scrollLeft+px)/zoom,wy=(viewport.scrollTop+py)/zoom;zoom=Math.max(.005,Math.min(3,value));applyZoom();viewport.scrollLeft=wx*zoom-px;viewport.scrollTop=wy*zoom-py;}
function fitAll(){if(!data.groups.length){zoom=.9;applyZoom();viewport.scrollTo(0,0);return;}zoom=Math.max(.005,Math.min(1,(viewport.clientWidth-60)/layout.width,(viewport.clientHeight-80)/layout.height));applyZoom();viewport.scrollTo(0,0);}
function focusEntity(id,single=false){const pos=layout.positions.get(id);if(!pos){if(data.photos[id]){trayOpen=true;renderTray();}return;}if(single)zoom=Math.min(2,(viewport.clientWidth-70)/Math.max(pos.w,200),(viewport.clientHeight-100)/Math.max(pos.h,230));else zoom=Math.min(1.05,Math.max(.4,(viewport.clientWidth-80)/Math.max(pos.w,360)));applyZoom();viewport.scrollTo({left:Math.max(0,pos.x*zoom-viewport.clientWidth/2),top:Math.max(0,pos.y*zoom-(single?viewport.clientHeight/2-pos.h*zoom/2:85)),behavior:'smooth'});}
function newGroup(){const g=commit(()=>{const n=M.group(data.groups.length);n.title='Group '+String(data.groups.length+1).padStart(2,'0');data.groups.push(n);selected=n.id;return n;},'Group added');if(g){focusEntity(g.id);setTimeout(()=>$('#detail-title')?.select(),100);}}
function splitPhoto(id){const n=commit(()=>{const n=M.splitAfter(data,id);selected=n.id;return n;},'Junction added. Your existing photos continue in the first branch.');if(n)focusEntity(n.id);}
async function showDialog(html){const d=$('#dialog');if(d.open)d.close();$('#dialog-content').innerHTML=html;d.showModal();hydrateIcons(d);}
function closeDialog(){$('#dialog').close();}
function openPhotoSizeDialog(){const size=data.photoSize??140;showDialog(`<form id="all-size-form"><h2>A closer look.</h2><p>Set the size of all photos, including new ones. To resize just one photo, select it and use its Photo size slider in Details.</p><div class="photo-size-label"><label class="detail-label" for="all-size-slider">All photos</label><output id="all-size-value" for="all-size-slider">${size} px</output></div><input type="range" class="size-slider" id="all-size-slider" min="100" max="360" step="10" value="${size}"><div class="size-hints"><span>Smaller</span><span>Larger</span></div><p class="detail-footnote">This replaces individual size adjustments. Image files stay the same.</p><div class="dialog-actions"><button type="button" class="button" data-close-dialog>Cancel</button><button class="button primary">Apply to all photos</button></div></form>`);$('#all-size-slider').oninput=e=>$('#all-size-value').textContent=e.target.value+' px';$('#all-size-form').onsubmit=e=>{e.preventDefault();const value=Number($('#all-size-slider').value);closeDialog();commit(()=>M.resizeAllPhotos(data,value),'Photo sizes updated');};}
function promptName(title,value,onSave){showDialog(`<form id="name-form"><h2>${title}</h2><label class="detail-label" for="name-value">Name</label><input id="name-value" class="detail-input" value="${esc(value)}" maxlength="200" required><div class="dialog-actions"><button type="button" class="button" data-close-dialog>Cancel</button><button class="button primary">Save name</button></div></form>`);$('#name-form').onsubmit=e=>{e.preventDefault();const v=$('#name-value').value.trim();if(v){closeDialog();onSave(v);}};$('#name-value').select();}
function confirmAction(title,message,label,onConfirm){showDialog(`<h2>${title}</h2><p>${message}</p><div class="dialog-actions"><button class="button" data-close-dialog>Cancel</button><button class="button danger" id="confirm-action">${label}</button></div>`);$('#confirm-action').onclick=()=>{closeDialog();onConfirm();};}
function moveDialog(){const f=M.find(data,selected);if(f?.type!=='photo')return;const list=M.chains(data);if(!list.length){toast('Add a group first, then move the photo into a chain.');return;}const id=selected;showDialog(`<form id="move-form"><h2>Find a new connection.</h2><p>Choose a chain for ${esc(f.entity.title)}. You can also drag it between photos on the canvas.</p><label class="detail-label" for="move-chain">Destination chain</label><select id="move-chain" class="detail-select">${list.map(c=>`<option value="${c.entity.id}">${esc(c.group.title+' / '+(c.parent.kind==='node'?c.parent.title+' / ':'')+c.entity.title)}</option>`).join('')}</select><label class="detail-label" for="move-position">Position</label><select id="move-position" class="detail-select"><option value="end">End of chain (before any junction)</option><option value="start">Beginning of chain</option></select><div class="dialog-actions"><button type="button" class="button" data-close-dialog>Cancel</button><button class="button primary">Move photo</button></div></form>`);$('#move-form').onsubmit=e=>{e.preventDefault();const cid=$('#move-chain').value,index=$('#move-position').value==='start'?0:undefined;closeDialog();commit(()=>M.movePhoto(data,id,cid,index),'Photo moved');focusEntity(id);};}
function exportBoard(){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=(data.title.replace(/[^a-z0-9]+/gi,'-').replace(/^-|-$/g,'')||'faceboard')+'.faceboard.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);toast('Backup exported, including all photos and connections.');}
function openGuide(){showDialog(`<h2>A little room for connections.</h2><p>Sort by eye, change your mind, and keep exploring. Here’s how the canvas works.</p><div class="guide-row">${ico('network')}<div><b>Groups live on the top bar.</b><p>Add a group, then select its tick to change the title, description, or color.</p></div></div><div class="guide-row">${ico('images')}<div><b>Photos follow a connected chain.</b><p>“Add photos” at the top opens your tray. “Add photos” beneath a chain adds directly to it. Drag to rearrange, or use “Move to a chain”.</p></div></div><div class="guide-row">${ico('branch')}<div><b>A junction opens new directions.</b><p>Select a photo and choose “Branch after this photo”. Existing photos below it become the first branch. Select any junction to add more chains later.</p></div></div><div class="guide-row">${ico('move')}<div><b>Go wide, or get a closer look.</b><p>Scroll in either direction. Hold Space and drag to pan. Use the zoom controls or Ctrl/⌘ + scroll. “Fit all” shows the whole board; “Focus” zooms to one entry.</p></div></div><div class="guide-row">${ico('shield')}<div><b>Keep a copy.</b><p>Your board saves in this browser on this device. Export includes your images. Import that backup from Workspace options. Photos are grouped manually; this app doesn’t identify people.</p></div></div><div class="dialog-actions"><button class="button primary" data-close-dialog>Let’s explore</button></div>`);}
function workspaceMenu(){showDialog(`<h2>Your workspace.</h2><p>A clean slate, a backup, or a little inspiration.</p><button class="menu-option" id="menu-rename">${ico('edit')} Rename workspace</button><button class="menu-option" id="menu-import">${ico('upload')} Import a Faceboard backup</button><button class="menu-option" id="menu-new">${ico('plus')} Start an empty workspace</button><button class="menu-option" id="menu-demo">${ico('spark')} Load the example board</button><div class="dialog-actions"><button class="button" data-close-dialog>Done</button></div>`);
  $('#menu-rename').onclick=()=>promptName('A name for this space.',data.title,v=>commit(()=>data.title=v));$('#menu-import').onclick=()=>{closeDialog();$('#import-input').click();};
  $('#menu-new').onclick=()=>confirmAction('Start with a clean canvas?','Export your current board first if you want a separate copy. This change can also be undone.','Start fresh',()=>{commit(()=>{data=M.empty();selected=null;},'A fresh workspace, ready for you.');fitAll();});
  $('#menu-demo').onclick=()=>confirmAction('Explore the example board?','Your current board will be replaced with illustrated sample portraits. Export a backup first to keep a separate copy. You can undo this change.','Load example',()=>{commit(()=>{data=M.demo();selected=null;},'Example board loaded');fitAll();});
}
function requestUpload(target=null,replaceId=null){uploadTarget={chain:target,replaceId};$('#photo-input').value='';$('#photo-input').click();}
function imageData(file){return new Promise((resolve,reject)=>{if(file.size>50*1024*1024)return reject(Error(file.name+' is too large (maximum 50 MB).'));if(!file.type.startsWith('image/'))return reject(Error(file.name+' is not an image.'));const url=URL.createObjectURL(file),img=new Image();img.onload=()=>{try{const scale=Math.min(1,1600/Math.max(img.width,img.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);resolve(canvas.toDataURL('image/jpeg',.9));}catch{reject(Error('Could not read '+file.name));}finally{URL.revokeObjectURL(url);}};img.onerror=()=>{URL.revokeObjectURL(url);reject(Error('Could not open '+file.name+'. Try a JPEG, PNG, or WebP image.'));};img.src=url;});}
async function uploadFiles(files,target=null,replaceId=null){if(!files.length)return;toast('Preparing '+files.length+' photo'+(files.length===1?'':'s')+'…');const results=[];let failed=0;for(const file of files){try{results.push({file,src:await imageData(file)});}catch{failed++;}}if(!results.length){toast('No photos could be opened. Try JPEG, PNG, or WebP images under 50 MB.');return;}
  commit(()=>{if(replaceId&&data.photos[replaceId]){data.photos[replaceId].src=results[0].src;data.photos[replaceId].sample=false;selected=replaceId;}else{for(const {file,src}of results){const id=M.uid();data.photos[id]={kind:'photo',id,title:file.name.replace(/\.[^.]+$/,''),description:'',src,sample:false};if(target&&M.find(data,target)?.type==='chain')M.movePhoto(data,id,target);selected=id;}if(!target)trayOpen=true;}},`${replaceId?'Image replaced':results.length+' photo'+(results.length===1?'':'s')+' added'}${failed?' · '+failed+' file(s) could not be opened':''}`);
  if(target&&selected)focusEntity(selected);
}
const actions={
 'reset-photo-size':()=>commit(()=>delete data.photos[selected].size,'Photo size reset'),
 'new-chain':()=>{const f=M.find(data,selected);if(!f||!['node','group'].includes(f.type))return;commit(()=>{const c=M.chain('Branch '+String(f.entity.chains.length+1).padStart(2,'0'));f.entity.chains.push(c);selected=c.id;},'Another chain, ready to grow.');focusEntity(selected);},
 'upload-selection':()=>requestUpload(selected),
 'append-node':()=>{const n=commit(()=>{const n=M.appendNode(data,selected);selected=n.id;return n;});if(n)focusEntity(n.id);},
 'split-photo':()=>splitPhoto(selected),
 'move-photo':moveDialog,
 'to-tray':()=>commit(()=>{M.movePhoto(data,selected,null);trayOpen=true;},'Photo returned to the tray'),
 'replace-photo':()=>requestUpload(null,selected),
 'focus-selection':()=>focusEntity(selected,true),
 'close-details':()=>inspector.classList.remove('mobile-open'),
 'group-left':()=>shiftGroup(-1),
 'group-right':()=>shiftGroup(1),
 'delete-selection':()=>{const id=selected,f=M.find(data,id);if(!f)return;confirmAction('Remove '+esc(f.entity.title)+'?',f.type==='photo'?'This photo will be deleted from this board. You can undo the change.':'All photos inside this '+(f.type==='node'?'junction':f.type)+' will return to the photo tray. You can undo the change.','Remove',()=>commit(()=>{M.removeEntity(data,id);selected=null;if(f.type!=='photo')trayOpen=true;},'Removed · you can undo this change'));}
};
function shiftGroup(direction){const index=data.groups.findIndex(g=>g.id===selected);if(index<0||index+direction<0||index+direction>=data.groups.length)return;commit(()=>{const g=data.groups.splice(index,1)[0];data.groups.splice(index+direction,0,g);});focusEntity(selected);}
let suppressClickUntil=0;
document.addEventListener('click',event=>{
 if(performance.now()<suppressClickUntil){event.preventDefault();event.stopPropagation();return;}
 const target=event.target.closest('button,[data-select]');if(!target)return;
 if(target.hasAttribute('data-close-dialog')){closeDialog();return;}
 if(target.dataset.action){actions[target.dataset.action]?.();return;}
 if(target.dataset.split){splitPhoto(target.dataset.split);return;}
 if(target.dataset.uploadChain){requestUpload(target.dataset.uploadChain);return;}
 if(target.hasAttribute('data-new-group')){newGroup();return;}
 if(target.dataset.focusGroup){select(target.dataset.focusGroup);focusEntity(target.dataset.focusGroup);return;}
 if(target.dataset.color){commit(()=>M.find(data,selected).entity.color=target.dataset.color);return;}
 if(target.hasAttribute('data-toggle-tray')){trayOpen=!trayOpen;renderTray();return;}
 if(target.dataset.select){select(target.dataset.select);return;}
});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-photo]')){e.preventDefault();select(e.target.dataset.photo);}});
let drawTimer;
inspector.addEventListener('focusin',e=>{if(e.target.dataset.field||e.target.hasAttribute('data-photo-size'))dirtyField=false;});
inspector.addEventListener('input',e=>{if(!e.target.hasAttribute('data-photo-size'))return;const f=M.find(data,selected);if(f?.type!=='photo')return;if(!dirtyField){remember();dirtyField=true;}const before=layout.positions.get(selected),oldX=before?.x,oldY=before?.y;M.resizePhoto(data,selected,e.target.value);$('#detail-size-value').textContent=M.photoDimensions(f.entity,data.photoSize).width+' px';renderCanvas();const after=layout.positions.get(selected);if(after&&before){viewport.scrollLeft+=(after.x-oldX)*zoom;viewport.scrollTop+=(after.y-oldY)*zoom;}save();});
inspector.addEventListener('input',e=>{const field=e.target.dataset.field;if(!field)return;const f=M.find(data,selected);if(!f)return;if(!dirtyField){remember();dirtyField=true;}f.entity[field]=e.target.value;clearTimeout(drawTimer);drawTimer=setTimeout(()=>{renderCanvas();renderNavigation();renderTray();const h=inspector.querySelector('h2');if(field==='title'&&h)h.textContent=f.entity.title;},150);save();});
inspector.addEventListener('change',e=>{if(e.target.dataset.field==='title'&&!e.target.value.trim()){const f=M.find(data,selected);f.entity.title='Untitled '+f.type;e.target.value=f.entity.title;renderCanvas();save();}});
$('#add-photos').onclick=()=>requestUpload();$('#add-group').onclick=$('#add-group-small').onclick=newGroup;$('#export').onclick=exportBoard;$('#workspace-menu').onclick=workspaceMenu;$('#workspace-name').onclick=()=>promptName('A name for this space.',data.title,v=>commit(()=>data.title=v));$('#help').onclick=openGuide;$('#undo').onclick=undo;$('#redo').onclick=redo;$('#fit').onclick=$('#zoom-fit').onclick=fitAll;$('#zoom-in').onclick=()=>setZoom(zoom*1.25);$('#zoom-out').onclick=()=>setZoom(zoom/1.25);$('#zoom-value').onclick=()=>setZoom(1);$('#library-nav').onclick=()=>{trayOpen=!trayOpen;renderTray();};$('#canvas-nav').onclick=()=>{trayOpen=false;renderTray();inspector.classList.remove('mobile-open');};$('#dismiss-intro').onclick=()=>$('#canvas-intro').hidden=true;
$('#photo-input').onchange=async e=>{const target=uploadTarget;await uploadFiles([...e.target.files],target?.chain,target?.replaceId);};
$('#import-input').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;if(file.size>250*1024*1024){toast('That backup is too large to import (maximum 250 MB).');return;}try{const next=M.validate(JSON.parse(await file.text()));confirmAction('Open this backup?',`“${esc(next.title)}” contains ${Object.keys(next.photos).length} photos and ${next.groups.length} groups. It will replace the current board. You can undo the change.`,'Open backup',()=>{commit(()=>{data=next;selected=null;trayOpen=false;},'Backup restored');fitAll();});}catch(error){toast(error.message==='Unexpected end of JSON input'?'The backup file is incomplete.':error.message);}};
viewport.addEventListener('wheel',e=>{if(e.ctrlKey||e.metaKey){e.preventDefault();setZoom(zoom*Math.exp(-e.deltaY*.008),e.clientX,e.clientY);}},{passive:false});
document.addEventListener('keydown',e=>{const typing=e.target.matches('input,textarea,select,[contenteditable="true"]');if(!typing&&!$('#dialog').open){if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undo();}else if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='y'){e.preventDefault();redo();}else if(e.code==='Space'){e.preventDefault();spaceHeld=true;viewport.classList.add('space-ready');}else if(e.key==='Escape'){selected=null;inspector.classList.remove('mobile-open');render();}}});
document.addEventListener('keyup',e=>{if(e.code==='Space'){spaceHeld=false;viewport.classList.remove('space-ready');}});window.addEventListener('blur',()=>{spaceHeld=false;pan=null;viewport.classList.remove('space-ready','panning');});
viewport.addEventListener('pointerdown',e=>{if(e.button===1||(e.button===0&&(spaceHeld||e.target===viewport||e.target===sizer||e.target===world))){e.preventDefault();pan={x:e.clientX,y:e.clientY,left:viewport.scrollLeft,top:viewport.scrollTop};viewport.setPointerCapture(e.pointerId);viewport.classList.add('panning');}});
viewport.addEventListener('pointermove',e=>{if(pan){viewport.scrollLeft=pan.left-(e.clientX-pan.x);viewport.scrollTop=pan.top-(e.clientY-pan.y);}});viewport.addEventListener('pointerup',()=>{pan=null;viewport.classList.remove('panning');});viewport.addEventListener('pointercancel',()=>{pan=null;viewport.classList.remove('panning');});
function endDrag(){document.body.classList.remove('is-dragging');document.querySelectorAll('.dragging,.drop-active').forEach(e=>e.classList.remove('dragging','drop-active'));document.querySelector('.drag-ghost')?.remove();dragId=null;dragPoint=null;cancelAnimationFrame(dragRAF);}
function autoScroll(){if(!dragPoint)return;const r=viewport.getBoundingClientRect(),margin=65,{x,y}=dragPoint;let dx=0,dy=0;if(x>r.left&&x<r.right&&y>r.top&&y<r.bottom){if(x<r.left+margin)dx=-13;else if(x>r.right-margin)dx=13;if(y<r.top+margin)dy=-13;else if(y>r.bottom-margin)dy=13;viewport.scrollBy(dx,dy);}dragRAF=requestAnimationFrame(autoScroll);}
let pointerDrag=null;
document.addEventListener('pointerdown',e=>{const card=e.target.closest('[data-photo]');if(!card||e.button!==0||spaceHeld||e.target.closest('button'))return;pointerDrag={id:card.dataset.photo,x:e.clientX,y:e.clientY,card,active:false,pointerId:e.pointerId};card.setPointerCapture(e.pointerId);});
document.addEventListener('pointermove',e=>{
 if(!pointerDrag||e.pointerId!==pointerDrag.pointerId)return;
 const p=pointerDrag;if(!p.active&&Math.hypot(e.clientX-p.x,e.clientY-p.y)<6)return;
 e.preventDefault();
 if(!p.active){p.active=true;dragId=p.id;p.card.classList.add('dragging');document.body.classList.add('is-dragging');const ghost=document.createElement('div');ghost.className='drag-ghost';ghost.innerHTML=`<img src="${data.photos[p.id].src}" alt=""><span>${esc(data.photos[p.id].title)}</span>`;document.body.append(ghost);dragPoint={x:e.clientX,y:e.clientY};autoScroll();}
 dragPoint={x:e.clientX,y:e.clientY};const ghost=document.querySelector('.drag-ghost');ghost.style.left=(e.clientX+14)+'px';ghost.style.top=(e.clientY-35)+'px';
 const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-drop-chain],[data-drop-tray]');document.querySelectorAll('.drop-active').forEach(el=>{if(el!==target)el.classList.remove('drop-active');});target?.classList.add('drop-active');
},{passive:false});
document.addEventListener('pointerup',e=>{
 if(!pointerDrag||e.pointerId!==pointerDrag.pointerId)return;const p=pointerDrag;pointerDrag=null;if(!p.active)return;
 suppressClickUntil=performance.now()+350;const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-drop-chain],[data-drop-tray]'),cid=target?.dataset.dropChain;let index=target?.dataset.dropIndex!==undefined?Number(target.dataset.dropIndex):undefined;
 if(target?.dataset.photo&&e.clientY<target.getBoundingClientRect().top+target.getBoundingClientRect().height/2)index--;
 endDrag();if(target)commit(()=>{M.movePhoto(data,p.id,cid||null,index);selected=p.id;},cid?'Photo connected to its new chain.':'Photo returned to the tray');
});
document.addEventListener('pointercancel',()=>{pointerDrag=null;endDrag();});
document.addEventListener('dragstart',e=>{if(e.target.closest('[data-photo]'))e.preventDefault();});
document.addEventListener('dragover',e=>{if(dragId)dragPoint={x:e.clientX,y:e.clientY};const target=e.target.closest('[data-drop-chain],[data-drop-tray]'),files=[...(e.dataTransfer.types||[])].includes('Files');document.querySelectorAll('.drop-active').forEach(el=>{if(el!==target)el.classList.remove('drop-active');});if(target&&(dragId||files)){e.preventDefault();e.dataTransfer.dropEffect=files?'copy':'move';target.classList.add('drop-active');}else if(files&&e.target.closest('.canvas-area')){e.preventDefault();e.dataTransfer.dropEffect='copy';}});
document.addEventListener('drop',async e=>{const target=e.target.closest('[data-drop-chain],[data-drop-tray]'),files=[...e.dataTransfer.files],id=dragId;const chainId=target?.dataset.dropChain,index=target?.dataset.dropIndex!==undefined?Number(target.dataset.dropIndex):undefined;if(target&&(id||files.length)){e.preventDefault();endDrag();if(files.length)await uploadFiles(files,chainId);else{commit(()=>{M.movePhoto(data,id,chainId||null,index);selected=id;},chainId?'Photo connected to its new chain.':'Photo returned to the tray');}}else if(files.length&&e.target.closest('.canvas-area')){e.preventDefault();endDrag();await uploadFiles(files);}else endDrag();});document.addEventListener('dragend',endDrag);
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'&&data){clearTimeout(saveTimer);persist(saveRevision);}});
new ResizeObserver(()=>{if(data)applyZoom();}).observe(viewport);
async function boot(){const saved=await openStorage();try{data=saved?M.validate(saved):M.demo();}catch{data=M.demo();toast('The saved board could not be read. Import a backup to recover it.');}render();if(!data.groups.length)fitAll();if(!saved)save();if(storageMode==='memory')toast('Saving is unavailable in this browser. Export a backup before you close the board.');}
boot();
